"use client";

import { motion, useReducedMotion } from "framer-motion";

export function ContentCard({
  title,
  description,
  href,
}: {
  title: string;
  description: string;
  href: string;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.a
      href={href}
      whileHover={shouldReduceMotion ? undefined : { y: -4 }}
      transition={{ type: "spring", stiffness: 400, damping: 28 }}
      className="group relative flex w-full flex-col gap-3 overflow-hidden rounded-2xl border border-slate-200 bg-white p-6 transition-shadow duration-300 hover:border-slate-300 hover:shadow-xl dark:border-slate-700 dark:bg-neutral-950"
    >
      <span
        aria-hidden
        className="absolute inset-x-0 top-0 h-0.5 origin-left scale-x-0 bg-emerald-500 transition-transform duration-300 ease-out group-hover:scale-x-100"
      />
      <h3 className="text-lg font-semibold text-slate-900 transition-colors group-hover:text-emerald-700 dark:text-white dark:group-hover:text-emerald-400">
        {title}
      </h3>
      <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      <span className="mt-auto inline-flex items-center gap-1 text-sm font-medium text-emerald-700 dark:text-emerald-400">
        Read more
        <span aria-hidden className="inline-block transition-transform duration-300 ease-out group-hover:translate-x-1">
          →
        </span>
      </span>
    </motion.a>
  );
}
